"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Second backbone, after the old head is trained (docs/evaluation_protocol.md, section 17): the same
forward passes and read-out fit as on the first backbone, with Voxtral (scripts/bb2_voxtral.py) in VoxTurn's place.

Item sets (built on the laptop, where the front-end features live; the texts do not depend on the backbone, so they
are built by the first backbone's own code and checked against its stored files where those keep a text hash):
  train2c     every train window, situation texts with step 2c's saved false labels (p1v4_readout_2c.extract),
              batch 8 -> grounding/allclass2c/feats_train_2c.npz and grounding/allclass2d/sec8_train.npz
  devnat      every dev window, natural texts (p1v4_readout.extract "natural"), batch 8
              -> readout/feats_dev_natural.npz and ears_time/feats_dev.npz (per-second ears by window id)
  devgrd      the dev matched groups in the grounding package's ten conditions (p1v4_grounding.l1_cmd), batch 1
              -> grounding/dev/l1_<cond>.npz
  devnoise    the evidence-reliability grid on dev (p1v4_reliability_dev.forward): the matched groups at dclean and
              dnoise10 ... 40 in the conditions none, c0.99, mv0.99, truth, batch 1 -> reliability/dev/<lv>/l1_<c>.npz
  devoff      the decision-offset check (p1v4_readout_2d.offsets, G4b): the dev main-body S-move groups cut at -0.5,
              0, +0.5, +1.0 s around the decision point (the first backbone's stored windows, final/dev/offsets),
              text of the matched "none" condition, batch 1 -> offsets/dev/l1_d<offset>.npz
  trainnat    every train window, natural texts (p1v4_grounding.control_cmd), batch 8 -> grounding/control/
              feats_train_natural.npz (the natural-label control)
  trainstep2  every train window, step 2's edits (p1v4_readout.train_edits: ring-class labels decoupled), batch 8
              -> readout/feats_train_train.npz (also the ears probe's training set, p1v4_conditional.fit_probe)
  train2b     every train window, step 2b's edits (p1v4_readout_allclass.train_edits: all five classes), batch 8
              -> grounding/allclass/feats_train_allclass.npz
Fits (fitall, each skipped when its output exists): fit2c (p1v4_readout_2c.fit), control (p1v4_grounding.control_cmd's
fit), step 2 (p1v4_readout.fit), step 2b (p1v4_readout_allclass.fit), ears probe (p1v4_conditional.fit_probe), the
control's 8 starts (p1v4_control_starts.fit_cmd) and package v0.6's extra read-outs (p1v4_readout_extra.fit: shuffled
seconds, natural labels with whole-window or per-second ears over 8 seeds, 2c states and 2d refitted with seed 1).
Outputs keep the first backbone's file layout and keys under data/p1v4/runs_bb2/, so its evaluation code can read them
with the run folder redirected. Interface-only differences (as in bb2_voxtral.py): the ears are the language model's
audio tokens of the 8 s window (the first 100 of Voxtral's 375; per second the tokens whose centre falls in that
second, 12 or 13), 3,072-d; the option states are 2 x 3,072.
usage (repo root):
  laptop:  .venv-gpu/Scripts/python.exe -X utf8 scripts/bb2_pipeline.py items train2c|devnat|devgrd
  GPU:     a separate GPU job runs bb2_voxtral.py train, then this script:
           forward <set> | fit2d | fitall
"""
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

RUNS2 = "data/p1v4/runs_bb2"
ITEMS = f"{RUNS2}/items"
NTOK, TPS = 100, 12.5                                   # 8 s of Voxtral audio tokens; tokens per second
SEC_OF = np.floor((np.arange(NTOK) + 0.5) / TPS).astype(int)
OUTS = {"train2c": [f"{RUNS2}/grounding/allclass2c/feats_train_2c.npz", f"{RUNS2}/grounding/allclass2d/sec8_train.npz"],
        "devnat": [f"{RUNS2}/readout/feats_dev_natural.npz", f"{RUNS2}/ears_time/feats_dev.npz"]}
BATCH = {"train2c": 8, "devnat": 8, "devgrd": 1, "devnoise": 1, "trainnat": 8, "trainstep2": 8, "train2b": 8,
         "devoff": 1}
OUTS.update({"trainnat": [f"{RUNS2}/grounding/control/feats_train_natural.npz"],
             "trainstep2": [f"{RUNS2}/readout/feats_train_train.npz"],
             "train2b": [f"{RUNS2}/grounding/allclass/feats_train_allclass.npz"]})


# ------------------------------------------------------------------------------------------------ items (laptop)

def items(which):
    import p1v4_data as D
    import p1v4_readout as RO
    os.makedirs(ITEMS, exist_ok=True)
    t0 = time.time()
    if which == "train2c":
        import p1v4_readout_2c as R2C
        import p1v4_readout_allclass as AC
        rows = D.load_rows("train")
        wins = D.windows_of(rows, "train")
        rows_by = {(r["unit"], r["version"]): r for r in rows}
        edits = {k: [tuple(e) for e in v] for k, v in json.load(open(f"{R2C.OUT}/train_edits.json")).items()}
        ctx = AC.MultiEdited("train", edits)
        out = []
        for w in wins:
            r = rows_by[w["key"]]
            text, asks = ctx.situation(r, w["k"], "full")
            qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
            out.append({"id": w["id"], "unit": w["unit"], "path": w["path"], "text": text,
                        "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                        "gold": [-1 if w["gold"].get(q) is None else
                                 int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs]})
        z = np.load(f"{R2C.OUT}/feats_train_2c.npz")             # the first backbone's train forward: same items
        assert list(z["ids"]) == [it["id"] for it in out]
        assert list(z["q_task"]) == [q for it in out for q in it["qs"]]
        assert list(z["q_gold"]) == [g for it in out for g in it["gold"]]
        sets = {"train2c": out}
    elif which == "devoff":
        import p1v4_context as C
        import p1v4_grounding as G
        import p1v4_readout_2d as R2D
        rows, rows_by = G.load("dev")
        groups = [g for g in G.load_groups("dev") if g["part"] == "s_move" and rows_by[(g["unit"], "1")]["subset"] is None]
        ctx = G.matched_context(C.Context)("dev", groups, "none", rows_by)
        sets = {f"devoff_d{d:+.1f}": [] for d in R2D.OFFSETS}
        for g in groups:
            for v in g["versions"]:
                r = rows_by[(g["unit"], v)]
                p = r["points"][g["k"]]
                text, asks = ctx.situation(r, g["k"], "full")
                qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
                for d in R2D.OFFSETS:
                    path = f"data/p1v4/runs/final/dev/offsets/{g['unit']}_{v}_p{g['k']}_d{d:+.1f}.wav"
                    assert os.path.exists(path), path
                    sets[f"devoff_d{d:+.1f}"].append(
                        {"id": f"{g['unit']}|{v}|{g['k']}", "unit": g["unit"], "part": "s_move", "path": path,
                         "text": text, "marker": "agent" if p.get("assistant_speaking") else "user", "qs": qs,
                         "gold": [-1 if p["gold"].get(q) is None else
                                  int(p["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                         "real": False, "conf": -1.0, "text_sha": G.sha(text)})
        print(f"devoff: {len(groups)} groups", flush=True)
    elif which in ("trainnat", "trainstep2", "train2b"):
        import p1v4_context as C
        import p1v4_readout_allclass as AC
        rows = D.load_rows("train")
        wins = D.windows_of(rows, "train")
        rows_by = {(r["unit"], r["version"]): r for r in rows}
        labels = {}
        if which == "trainnat":
            ctx, ref = C.Context("train"), "data/p1v4/runs/grounding/control/feats_train_natural.npz"
        elif which == "trainstep2":
            edits, labels = RO.train_edits(rows)
            ctx, ref = RO.Edited("train", edits), f"{RO.OUT}/feats_train_train.npz"
        else:
            edits, _ = AC.train_edits(rows)
            ctx, ref = AC.MultiEdited("train", edits), f"{AC.OUT}/feats_train_allclass.npz"
        out = []
        for w in wins:
            r = rows_by[w["key"]]
            text, asks = ctx.situation(r, w["k"], "full")
            qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
            it = {"id": w["id"], "unit": w["unit"], "path": w["path"], "text": text,
                  "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                  "gold": [-1 if w["gold"].get(q) is None else
                           int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs]}
            if which == "trainstep2":
                snd = [s for s in ctx.point(r, w["k"])[3] if RO.in_window(s, w["t"])]
                it.update(part=w["part"], real=RO.is_real(r, w["t"]), conf=max([s[3] for s in snd], default=-1.0),
                          cond=labels.get(w["id"], "unedited"))
            out.append(it)
        z = np.load(ref)
        assert list(z["ids"]) == [it["id"] for it in out], which
        assert list(z["q_task"]) == [q for it in out for q in it["qs"]], which
        assert list(z["q_gold"]) == [g for it in out for g in it["gold"]], which
        if which == "trainstep2":
            assert list(z["cond"]) == [it["cond"] for it in out]
            assert list(z["real"]) == [it["real"] for it in out]
            assert np.allclose(z["conf"], [it["conf"] for it in out])
        sets = {which: out}
    elif which == "devnat":
        rows = D.load_rows("dev")
        wins = D.windows_of(rows, "dev")
        rows_by = {(r["unit"], r["version"]): r for r in rows}
        ctx = RO.Edited("dev", RO.dev_edits(rows, "natural"))
        out = []
        for w in wins:
            r = rows_by[w["key"]]
            text, asks = ctx.situation(r, w["k"], "full")
            qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
            snd = [s for s in ctx.point(r, w["k"])[3] if RO.in_window(s, w["t"])]
            out.append({"id": w["id"], "unit": w["unit"], "part": w["part"], "path": w["path"], "text": text,
                        "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                        "gold": [-1 if w["gold"].get(q) is None else
                                 int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                        "real": RO.is_real(r, w["t"]), "conf": max([s[3] for s in snd], default=-1.0),
                        "cond": "unedited"})
        z = np.load(f"{RO.OUT}/feats_dev_natural.npz")
        assert list(z["ids"]) == [it["id"] for it in out]
        assert list(z["q_task"]) == [q for it in out for q in it["qs"]]
        sets = {"devnat": out}
    elif which == "devgrd":
        import p1v4_context as C
        import p1v4_grounding as G
        rows, rows_by = G.load("dev")
        groups = G.load_groups("dev")
        keys = {(g["unit"], v, g["k"]) for g in groups for v in g["versions"]}
        wins = [w for w in D.windows_of(rows, "dev") if (w["unit"], w["version"], w["k"]) in keys]
        M = G.matched_context(C.Context)
        part_of = {g["unit"]: g["part"] for g in groups}
        sets = {}
        for cond in G.ALL_CONDS:
            ctx = M("dev", groups, cond, rows_by, final=False)
            out = []
            for w in wins:
                if G.is_move(cond) and part_of[w["unit"]] != "s_move":
                    continue
                r = rows_by[(w["unit"], w["version"])]
                text, asks = ctx.situation(r, w["k"], "full")
                qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
                snd = [s for s in ctx.point(r, w["k"])[3] if RO.in_window(s, w["t"])]
                out.append({"id": w["id"], "unit": w["unit"], "part": w["part"], "path": w["path"], "text": text,
                            "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                            "gold": [-1 if w["gold"].get(q) is None else
                                     int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                            "real": RO.is_real(r, w["t"]), "conf": max([s[3] for s in snd], default=-1.0),
                            "text_sha": G.sha(text)})
            z = np.load(f"{G.out_dir('dev')}/l1_{cond}.npz")
            assert list(z["ids"]) == [it["id"] for it in out], cond
            assert list(z["text_sha"]) == [it["text_sha"] for it in out], f"{cond}: texts differ from backbone 1"
            sets[f"devgrd_{cond}"] = out
    elif which == "devnoise":
        import p1v4_context as C
        import p1v4_grounding as G
        import p1v4_noise_final as NF
        import p1v4_reliability_dev as RD
        NF.patch_folders()
        rows, rows_by = G.load("dev")
        groups = G.load_groups("dev")
        part_of = {g["unit"]: g["part"] for g in groups}
        keys = {(g["unit"], v, g["k"]) for g in groups for v in g["versions"]}
        wins = [w for w in D.windows_of(rows, "dev") if (w["unit"], w["version"], w["k"]) in keys]
        paths = {"dclean": {(w["unit"], w["version"], w["k"]): w["path"] for w in wins}}
        for lv in RD.LEVELS[1:]:
            rv = D.load_rows(f"dev_{lv}")
            paths[lv] = {(w["unit"], w["version"], w["k"]): w["path"] for w in D.windows_of(rv, f"dev_{lv}")
                         if (w["unit"], w["version"], w["k"]) in keys}
            assert set(paths[lv]) == keys, lv
        M, T = G.matched_context(C.Context), RD.truth_context(C.Context)
        ctx = {c: (T if c == "truth" else M)("dev", groups, c, rows_by, final=False) for c in RD.CONDS}
        sets = {}
        for cond in RD.CONDS:
            base = []
            for w in wins:
                part = part_of[w["unit"]]
                if (cond == "c0.99" and part != "r_hear") or (cond == "mv0.99" and part != "s_move"):
                    continue
                r = rows_by[(w["unit"], w["version"])]
                text, asks = ctx[cond].situation(r, w["k"], "full")
                qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
                snd = [s for s in ctx[cond].point(r, w["k"])[3] if RO.in_window(s, w["t"])]
                base.append({"id": w["id"], "unit": w["unit"], "part": w["part"],
                             "key": [w["unit"], w["version"], w["k"]], "text": text,
                             "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                             "gold": [-1 if w["gold"].get(q) is None else
                                      int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                             "real": RO.is_real(r, w["t"]), "conf": max([s[3] for s in snd], default=-1.0),
                             "text_sha": G.sha(text)})
            for lv in RD.LEVELS:
                out = [dict(it, path=paths[lv][tuple(it["key"])]) for it in base]
                z = np.load(f"{RD.OUT}/{lv}/l1_{cond}.npz")
                assert list(z["ids"]) == [it["id"] for it in out], (lv, cond)
                assert list(z["text_sha"]) == [it["text_sha"] for it in out], f"{lv}/{cond}: texts differ"
                sets[f"devnoise_{lv}_{cond}"] = out
    else:
        raise SystemExit(f"unknown set {which}")
    for name, out in sets.items():
        json.dump(out, open(f"{ITEMS}/{name}.json", "w"))
        print(f"{name}: {len(out)} windows, {sum(len(it['qs']) for it in out)} questions", flush=True)
    print(f"items {which}: {time.time() - t0:.0f} s; " + ("windows of the first backbone's offsets run (its texts "
          "were not stored)" if which == "devoff" else "equal to the first backbone's stored inputs"), flush=True)


# ------------------------------------------------------------------------------------------------ forward (GPU)

def forward_states_vx(model, waves, texts, markers, qlists):
    """= p1v4_readout.forward_states with the Voxtral model, except that the ears are the window's 100 audio tokens;
    also returns the per-second ears (B, 8, d) mean and max from the same audio tokens."""
    import torch
    import torch.nn as nn
    import torch.nn.functional as F
    import p1v4_l1 as L1
    vt, mod = model.vt, model.mod
    dev = vt.head.weight.device
    emb = vt.llm.get_input_embeddings()
    with torch.no_grad(), torch.autocast("cuda", dtype=torch.bfloat16):
        audio = vt.encode_audio(vt.mel(waves))
        seqs, opt_pos, blocks = [], [], []
        for b in range(len(texts)):
            ids = vt.context_ids(texts[b], markers[b], "en", L1.MAX_TEXT_TOKENS)
            prefix = torch.cat([emb(torch.tensor(vt.seq_head + vt.audio_open, device=dev)), audio[b],
                                emb(torch.tensor(vt.audio_close + ids, device=dev))], 0)
            parts, start, spans = [prefix], len(prefix), []
            for task in qlists[b]:
                q_ids, q_pos = vt.prompt(task, "en", 0)
                parts.append(emb(torch.tensor(q_ids, device=dev)))
                opt_pos.append([start + p for p in q_pos])
                spans.append((start, len(q_ids)))
                start += len(q_ids)
            seqs.append(torch.cat(parts, 0))
            blocks.append(spans)
        x = nn.utils.rnn.pad_sequence(seqs, batch_first=True)
        x = F.pad(x, (0, 0, 0, -x.shape[1] % mod.LEN_BUCKET))
        if any(len(s) > 1 for s in blocks):
            kw = vt.isolating_mask(blocks, x.shape[1], dev)
            hid = vt.llm(inputs_embeds=x, attention_mask=kw["attention_mask"],
                         position_ids=kw["position_ids"]).last_hidden_state
        else:
            hid = vt.llm(inputs_embeds=x).last_hidden_state
        q_seq = torch.tensor([i for i, spans in enumerate(blocks) for _ in spans], device=dev)
        pos = torch.tensor(opt_pos, device=dev)
        h = hid[q_seq[:, None], pos].float()
    with torch.no_grad():
        p_old = model.new_head(h).squeeze(-1).softmax(-1)[:, 1]
        a = audio[:, :NTOK].float()
        sec = torch.as_tensor(SEC_OF, device=a.device)
        sm = torch.stack([a[:, sec == s].mean(1) for s in range(8)], 1)
        sx = torch.stack([a[:, sec == s].amax(1) for s in range(8)], 1)
        ears = torch.cat([a.mean(1), a.amax(1)], -1)
    return (h.reshape(h.shape[0], -1).cpu().numpy(), ears.cpu().numpy(), q_seq.cpu().numpy(), p_old.cpu().numpy(),
            sm.cpu().numpy(), sx.cpu().numpy())


def forward(which):
    import soundfile as sf
    import torch
    import bb2_voxtral as BV
    import p1v4_l1 as L1
    TASK = {"S": "stop", "R": "respond"}
    names = sorted(f[:-5] for f in os.listdir(ITEMS) if f.startswith(which) and f.endswith(".json"))
    model = BV.build()
    L1.load_new_state(model, torch.load(f"{RUNS2}/l1/l1_new.pt", weights_only=True))
    model.eval()
    B = BATCH[which]
    for name in names:
        if which == "devgrd":
            cond = name[len("devgrd_"):]
            outs = [f"{RUNS2}/grounding/dev/l1_{cond}.npz"]
        elif which == "devnoise":
            lv, cond = name[len("devnoise_"):].split("_", 1)
            outs = [f"{RUNS2}/reliability/dev/{lv}/l1_{cond}.npz"]
        elif which == "devoff":
            outs = [f"{RUNS2}/offsets/dev/l1_{name[len('devoff_'):]}.npz"]
        else:
            outs = OUTS[which]
        if all(os.path.exists(o) for o in outs):
            print(f"{name}: exists, skipped", flush=True)
            continue
        its = json.load(open(f"{ITEMS}/{name}.json"))
        H, E, SM, SX, QW, QT, QG, PO = [], [], [], [], [], [], [], []
        t0 = time.time()
        for i in range(0, len(its), B):
            chunk = its[i:i + B]
            waves = torch.stack([torch.from_numpy(sf.read(BV.local_path(it["path"]), dtype="float32")[0])
                                 for it in chunk]).cuda()
            h, e, qw, po, sm, sx = forward_states_vx(model, waves, [it["text"] for it in chunk],
                                                     [it["marker"] for it in chunk],
                                                     [[TASK[q] for q in it["qs"]] for it in chunk])
            H.append(h.astype(np.float16))
            E.append(e.astype(np.float16))
            SM.append(sm.astype(np.float16))
            SX.append(sx.astype(np.float16))
            QW.append(qw + i)
            QT += [q for it in chunk for q in it["qs"]]
            QG += [g for it in chunk for g in it["gold"]]
            PO.append(po)
            if (i // B) % (500 if B > 1 else 300) == 0:
                print(f"{name}: {i + len(chunk)}/{len(its)} windows {time.time() - t0:.0f} s", flush=True)
        for o in outs:
            os.makedirs(os.path.dirname(o), exist_ok=True)
        ids = np.array([it["id"] for it in its])
        if which == "train2c":
            np.savez(outs[0], states=np.concatenate(H), ears=np.concatenate(E), q_win=np.concatenate(QW),
                     q_task=np.array(QT), q_gold=np.array(QG), ids=ids, units=np.array([it["unit"] for it in its]))
            np.savez(outs[1], ids=ids, sec_mean=np.concatenate(SM), sec_max=np.concatenate(SX))
        elif which == "trainnat":
            np.savez(outs[0], states=np.concatenate(H), q_win=np.concatenate(QW), q_task=np.array(QT),
                     q_gold=np.array(QG), ids=ids, units=np.array([it["unit"] for it in its]))
        elif which == "trainstep2":
            np.savez(outs[0], states=np.concatenate(H), ears=np.concatenate(E), q_win=np.concatenate(QW),
                     q_task=np.array(QT), q_gold=np.array(QG), p_old=np.concatenate(PO), ids=ids,
                     units=np.array([it["unit"] for it in its]), parts=np.array([it["part"] for it in its]),
                     real=np.array([it["real"] for it in its]), conf=np.array([it["conf"] for it in its]),
                     cond=np.array([it["cond"] for it in its]))
        elif which == "train2b":
            np.savez(outs[0], states=np.concatenate(H), ears=np.concatenate(E), q_win=np.concatenate(QW),
                     q_task=np.array(QT), q_gold=np.array(QG), ids=ids, units=np.array([it["unit"] for it in its]))
        elif which == "devnat":
            np.savez(outs[0], states=np.concatenate(H), ears=np.concatenate(E), q_win=np.concatenate(QW),
                     q_task=np.array(QT), q_gold=np.array(QG), p_old=np.concatenate(PO), ids=ids,
                     units=np.array([it["unit"] for it in its]), parts=np.array([it["part"] for it in its]),
                     real=np.array([it["real"] for it in its]), conf=np.array([it["conf"] for it in its]),
                     cond=np.array([it["cond"] for it in its]))
            np.savez(outs[1], ids=ids, sec_mean=np.concatenate(SM), sec_max=np.concatenate(SX))
        else:
            np.savez(outs[0], states=np.concatenate(H), ears=np.concatenate(E), sec_mean=np.concatenate(SM),
                     sec_max=np.concatenate(SX), q_win=np.concatenate(QW), q_task=np.array(QT),
                     q_gold=np.array(QG), p_old=np.concatenate(PO), ids=ids,
                     units=np.array([it["unit"] for it in its]), parts=np.array([it["part"] for it in its]),
                     real=np.array([it["real"] for it in its]), conf=np.array([it["conf"] for it in its]),
                     text_sha=np.array([it["text_sha"] for it in its]))
        print(f"{name} done: {len(its)} windows, {len(QT)} questions, {time.time() - t0:.0f} s", flush=True)
        if which == "devnat":                    # the old head here must equal the training run's dev scores
            sc = {tuple(k.split("|")[:2]) + (int(k.split("|")[2]),): v
                  for k, v in json.load(open(f"{RUNS2}/l1/scores_dev.json")).items()}
            qw, po = np.concatenate(QW), np.concatenate(PO)
            diff = [abs(sc[tuple(its[w]["id"].split("|")[:2]) + (int(its[w]["id"].split("|")[2]),)][q] - p)
                    for w, q, p in zip(qw, QT, po)]
            print(f"check vs the training run's dev scores: max |diff| {max(diff):.5f}, median "
                  f"{np.median(diff):.6f}", flush=True)


def fit2d():
    """p1v4_readout_2d.fit on the second backbone's train forward (run folder redirected)."""
    import p1v4_readout_2c as R2C
    import p1v4_readout_2d as R2D
    R2C.OUT = f"{RUNS2}/grounding/allclass2c"
    R2D.OUT = f"{RUNS2}/grounding/allclass2d"
    t0 = time.time()
    R2D.fit()
    print(f"fit2d done in {time.time() - t0:.0f} s", flush=True)


def fitall():
    """The other read-outs and the ears probe of the first backbone's chain, each by its own fit code with the run
    folder redirected; a step whose output exists is skipped."""
    import p1v4_conditional as CV
    import p1v4_control_starts as CS
    import p1v4_grounding as G
    import p1v4_readout as RO
    import p1v4_readout_2c as R2C
    import p1v4_readout_2d as R2D
    import p1v4_readout_allclass as AC
    import p1v4_readout_extra as RX
    RO.OUT, R2C.OUT, AC.OUT, CV.OUT, G.R = (f"{RUNS2}/readout", f"{RUNS2}/grounding/allclass2c",
                                            f"{RUNS2}/grounding/allclass", f"{RUNS2}/readout", RUNS2)
    R2D.OUT, RX.R, RX.OUT, CS.CDIR = (f"{RUNS2}/grounding/allclass2d", RUNS2, f"{RUNS2}/grounding/extra",
                                      f"{RUNS2}/grounding/control")
    nat = f"{RUNS2}/grounding/control/feats_train_natural.npz"
    steps = (("fit2c", R2C.fit, f"{R2C.OUT}/feats_train_2c.npz", f"{R2C.OUT}/readouts_2c.npz"),
             ("control", G.control_cmd, f"{RUNS2}/grounding/control/feats_train_natural.npz",
              f"{RUNS2}/grounding/control/control_readouts.npz"),
             ("step 2", RO.fit, f"{RO.OUT}/feats_train_train.npz", f"{RO.OUT}/readouts.npz"),
             ("step 2b", AC.fit, f"{AC.OUT}/feats_train_allclass.npz", f"{AC.OUT}/readouts_allclass.npz"),
             ("ears probe", CV.fit_probe, f"{RO.OUT}/feats_train_train.npz", f"{RO.OUT}/ears_probe.npz"),
             ("control starts", CS.fit_cmd, f"{RUNS2}/grounding/control/control_readouts.npz", CS.start_path(7)),
             ("extra read-outs", RX.fit, nat, RX.path_of(RX.NAMES[-1])))
    for name, fn, inp, out in steps:
        if os.path.exists(out):
            print(f"{name}: exists, skipped", flush=True)
            continue
        if not os.path.exists(inp):          # never let a fit run its own (first-backbone) forward
            print(f"{name}: input {inp} not there yet, skipped", flush=True)
            continue
        t0 = time.time()
        fn()
        assert os.path.exists(out), f"{name}: {out} was not written"
        print(f"{name} fitted in {time.time() - t0:.0f} s", flush=True)


if __name__ == "__main__":
    if len(sys.argv) >= 3 and sys.argv[1] == "items":
        items(sys.argv[2])
    elif len(sys.argv) >= 3 and sys.argv[1] == "forward":
        forward(sys.argv[2])
    elif len(sys.argv) == 2 and sys.argv[1] == "fit2d":
        fit2d()
    elif len(sys.argv) == 2 and sys.argv[1] == "fitall":
        fitall()
    else:
        raise SystemExit(__doc__)
